from rcb_client import Robot
from pathlib import Path
from PIL import Image
from scipy.ndimage import label
import numpy as np,json
r=Robot();o=r.get_obs(depth=True);d=Path('/app/output/runs/current');d.mkdir(exist_ok=True)
(d/'meta.json').write_text(json.dumps(o.meta,indent=2))
for c,a in o.last.items():Image.fromarray(a).save(d/f'{c}.png')
for c,a in o.last_depth.items():np.save(d/f'{c}_depth.npy',a)
n=np.array(o.meta['proprio']['now'],float);seed=np.r_[n[:7],n[8:15]]
E=np.eye(4);E[:3]=o.meta['cameras']['ego']['extrinsic_cv'];Ei=np.linalg.inv(E);D=o.last_depth['ego']; vv,uu=np.indices(D.shape);X=(uu-424)*D/376.7245385;Y=(vv-240)*D/376.7245385;zw=Ei[2,0]*X+Ei[2,1]*Y+Ei[2,2]*D+Ei[2,3];xw=Ei[0,0]*X+Ei[0,1]*Y+Ei[0,2]*D+Ei[0,3];yw=Ei[1,0]*X+Ei[1,1]*Y+Ei[1,2]*D+Ei[1,3]
mask=(zw>.766)&(zw<.84)&(uu>350)&(uu<530)&(vv>350)&(vv<470)&(D>0);lab,nlab=label(mask); print('time',o.meta['time_left_s'],'tcp',n[16:23],'grip',n[7]);
for i in range(1,nlab+1):
 ys,xs=np.where(lab==i)
 if len(xs)>20:print('blob',len(xs),(xs.min(),xs.max(),ys.min(),ys.max()),np.round([np.mean(xw[ys,xs]),np.mean(yw[ys,xs]),np.mean(zw[ys,xs])],3))
q=[0,.70710678,.70710678,0]
for p in [[.26,-.03,.80],[.26,-.03,.78],[.27,-.04,.78],[.25,-.02,.78],[.28,-.03,.78]]:
 a=r.ik({'Gripper_Tip_R':[*p,*q]},seed=seed);print('IK',p,a['ok'],a['error']['Gripper_Tip_R'],np.round(a['q'][:7],2))
